+  id: 'BenchZip',
+  label: new TranslatableMarkup('Bench postal code', [], ['context' => 'Validation'])
+)]
+class BenchZipConstraint extends SymfonyConstraint {
+
+  #[HasNamedArguments]
+  public function __construct(
+    mixed $options = NULL,
+    public $message = '%value is not a valid postal code.',
+    ?array $groups = NULL,
+    mixed $payload = NULL,
+  ) {
+    parent::__construct($options, $groups, $payload);
+  }
+
+}
diff --git a/web/modules/custom/bench_zip/src/Plugin/Validation/Constraint/BenchZipConstraintValidator.php b/web/modules/custom/bench_zip/src/Plugin/Validation/Constraint/BenchZipConstraintValidator.php
