@@ -0,0 +1,46 @@
+<?php
+
+declare(strict_types = 1);
+
+namespace Drupal\bench_zip\Plugin\Validation\Constraint;
+
+use Symfony\Component\Validator\Constraint;
+use Symfony\Component\Validator\ConstraintValidator;
+use Symfony\Component\Validator\Exception\UnexpectedTypeException;
+
+/**
+ * Validates postal codes against the five-digit format.
+ */
+class BenchZipConstraintValidator extends ConstraintValidator {
+
+  /**
+   * {@inheritdoc}
+   *
+   * @throws \Symfony\Component\Validator\Exception\UnexpectedTypeException
+   *   Thrown when the given constraint is not supported by this validator.
+   */
+  public function validate($value, Constraint $constraint): void {
+    if (!$constraint instanceof BenchZipConstraint) {
+      throw new UnexpectedTypeException($constraint, BenchZipConstraint::class);
+    }
+
+    // Null means there is no value to check; presence is a separate rule.
+    if ($value === NULL) {
+      return;
+    }
+
+    if (!is_string($value) && !is_int($value)) {
+      $this->context->buildViolation($constraint->message)
+        ->setParameter('%value', gettype($value))
+        ->addViolation();
+      return;
+    }
+
+    if (!preg_match('/^\d{5}$/D', (string) $value)) {
+      $this->context->buildViolation($constraint->message)
+        ->setParameter('%value', (string) $value)
+        ->addViolation();
+    }
+  }
+
+}

