+<?php
+
+declare(strict_types=1);
+
+namespace Drupal\bench_retitle\Hook;
+
+use Drupal\Core\Hook\Attribute\Hook;
+use Drupal\Core\State\StateInterface;
+use Drupal\node\NodeInterface;
+
+/**
+ * Hook implementations for bench_retitle.
+ */
+class RetitleHooks {
+
+  public function __construct(
+    protected readonly StateInterface $state,
+  ) {}
+
+  /**
+   * Implements hook_node_presave().
+   */
+  #[Hook('node_presave')]
+  public function nodePresave(NodeInterface $node): void {
+    // New nodes have no previous title to compare against.
+    if ($node->isNew() || !isset($node->original)) {
+      return;
+    }
+    $old_title = $node->original->getTitle();
+    $new_title = $node->getTitle();
+    if ($old_title === $new_title) {
+      return;
+    }
+    $log = $this->state->get('bench_retitle.log', []);
+    $log[] = $old_title . ' -> ' . $new_title;
+    $this->state->set('bench_retitle.log', $log);
+  }
+
+}
